const largestPrimeFactor = (n) => {
  let largest = -1;
  let num = n;

  // Divide out all factors of 2
  while (num % 2 === 0) {
    largest = 2;
    num /= 2;
  }

  // Check odd factors from 3 up to sqrt(num)
  for (let i = 3; i * i <= num; i += 2) {
    while (num % i === 0) {
      largest = i;
      num /= i;
    }
  }

  // If num is still greater than 1, then it is a prime factor
  if (num > 1) {
    largest = num;
  }

  return largest;
};
